/// Whether the harness is working on a prompt or a question, compiling or
/// running it.
/// What is running: the task the harness is working on, then each
/// question still running.
pub fn running_jobs(&self) -> Vec<Job> {
    let task = self
        .tasks
        .last()
        .filter(|task| self.working && task.status.is_active())
        .map(|task| Job {
            kind: JobKind::Task,
            title: "Task".into(),
            detail: Some(first_line(&task.text)),
        });
    let questions = self
        .asks
        .iter()
        .filter(|ask| ask.task.status.is_active())
        .map(|ask| Job {
            kind: JobKind::Question(ask.id),
            title: "Question".into(),
            detail: Some(first_line(&ask.task.text)),
        });
    task.into_iter().chain(questions).collect()
}

/// Starts a question that stays running, for tests elsewhere.
#[cfg(test)]
pub fn start_test_question(&mut self, text: &str, cx: &mut Context<Self>) -> usize {
        match &job.detail {
            Some(detail) => format!("{}: {detail}", job.title).into(),
            None => job.title.clone(),
        }
    } else {
        format!("{count} things running").into()
    };
    let list = self.jobs_open.then(|| {
        let rows = self.jobs.iter().enumerate().map(|(ix, job)| {
            let kind = job.kind;
            let row = h_flex()
                .id(("ribbon-job", ix))
                .gap_2()
                .px_3()
                .py_1p5()
                .rounded(theme.radius)
                .cursor_pointer()
                .hover(|row| row.bg(theme.list_hover))
                .on_click(cx.listener(move |this, _, _, cx| {
                    this.jobs_open = false;
                    cx.emit(RevealJob(kind));
                    cx.notify();
                }))
                .child(gpui_kit::component::spinner::Spinner::new().small())
                .child(div().flex_none().font_medium().child(job.title.clone()))
                .children(job.detail.clone().map(|detail| {
                    div()
                        .flex_1()
                        .min_w_0()
                        .truncate()
                        .text_color(theme.muted_foreground)
        titlebar: Some(TitlebarOptions {
            title: Some(APP_TITLE.into()),
            ..Default::default()
        }),
        ..Default::default()
    };

    cx.open_window(options, |window, cx| {
        // Start in the saved light or dark mode, else the system's; the
        // ribbon can switch.
        theme_preference::apply(window, cx);
        let view = cx.new(|cx| MainWindow::new(window, cx));
        cx.new(|cx| Root::new(view, window, cx))
    })
}

pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
    let ribbon = cx.new(Ribbon::new);
    let sidebar = cx.new(ProjectTree::new);
    let prompt_mode = cx.new(|cx| PromptMode::new(window, cx));
    let mut subscriptions = vec![
        // The ribbon's activity spinner follows whatever is running.
        cx.observe(&prompt_mode, |this, _, cx| this.refresh_jobs(cx)),
        cx.observe(&ribbon, |this, _, cx| this.refresh_jobs(cx)),
        // The project indicator's "Open Project…".
        cx.subscribe_in(
            &ribbon.read(cx).project_indicator().clone(),
            window,
            |this, _, _: &OpenProject, window, cx| this.open_project_picker(window, cx),
        ),
        cx.subscribe_in(&ribbon, window, |this, _, RevealJob(kind), window, cx| {
            this.reveal_job(*kind, window, cx)
        }),
        cx.subscribe_in(&sidebar, window, |this, _, OpenFile(path), window, cx| {
            this.prompt_mode.update(cx, |prompt_mode, cx| {
                prompt_mode.open_file(path.clone(), window, cx)
            })
        }),
        cx.subscribe_in(&sidebar, window, |this, _, OpenDiff(path), window, cx| {
            this.open_diff(path.clone(), window, cx)
        }),

