/// Runs `piton build` in the project, then says how it went.
pub fn build(&mut self, window: &mut Window, cx: &mut Context<Self>) {
    let Some(dir) = ProjectDirectory::get(cx).filter(|_| !self.building) else {
        return;
    };
    self.building = true;
    cx.notify();

    let build = piton_build::run(dir, cx);
    cx.spawn_in(window, async move |this, cx| {
        let result = build.await;
        this.update_in(cx, |this, window, cx| {
            this.building = false;
            cx.notify();
            let note = match result {
                Ok(outcome) if outcome.success => {
                    let title = match outcome.files.len() {
                        1 => "Built 1 file".to_string(),
                        count => format!("Built {count} files"),
                    };
                    let files = outcome.files;
                    Notification::success("")
                        .title(title)
                        .content(move |_, _, _| {
                            // One line per written file, never wrapped.
                            gpui_kit::component::v_flex()
                                .children(files.iter().map(|file| {
                                    gpui_kit::component::label::Label::new(file.clone())
                                        .whitespace_nowrap()
                                        .truncate()
                                }))
                                .into_any_element()
                        })
                }
                Ok(outcome) => Notification::error(outcome.report).title("Build failed"),
                Err(err) => {
                    Notification::error(err.to_string()).title("Could not run piton build")
                }
            };
            window.push_notification(note, cx);
fn showing_divergence(&self) -> bool {
    self.divergence.is_some() && !self.divergence_minimized
}

/// Tells the ribbon everything running: a spec build, the task and
/// questions, and a divergence analysis.
fn refresh_jobs(&mut self, cx: &mut Context<Self>) {
    let mut jobs = Vec::new();
    if self.ribbon.read(cx).is_building() {
        jobs.push(Job {
            kind: JobKind::Build,
            title: "Building the spec".into(),
            detail: None,
        });
    }
    jobs.extend(self.prompt_mode.read(cx).running_jobs());
    if self
        .divergence
        .as_ref()
        .is_some_and(|view| view.read(cx).is_running())
    {
        jobs.push(Job {
            kind: JobKind::Divergence,
            title: "Analyzing divergence".into(),
            detail: None,
        });
    }
    if self
        .rescope
        .as_ref()
        .is_some_and(|view| view.read(cx).is_running())
    {
        jobs.push(Job {
            kind: JobKind::Rescope,
            title: "Finding scopes to extract".into(),
            detail: None,
        });
    }
    self.ribbon
        .update(cx, |ribbon, cx| ribbon.set_jobs(jobs, cx));
}

/// Reveals a running job: the task or question behind any inset panel,
/// or the divergence panel.
pub fn reveal_job(&mut self, kind: JobKind, window: &mut Window, cx: &mut Context<Self>) {
    match kind {
        JobKind::Build => {}
        JobKind::Divergence => {
            if let Some(view) = self.divergence.clone() {
                self.restore_divergence(&view, window, cx);
            }
        }
        JobKind::Rescope => {
            if let Some(view) = self.rescope.clone() {
                self.restore_rescope(&view, window, cx);
            }
        }
        JobKind::Task | JobKind::Question(_) => {
            if self.showing_divergence() {
                self.minimize_divergence(window, cx);
            } else if self.showing_rescope() {
                self.minimize_rescope(window, cx);
            } else if self.panel_open() {
                self.close_panel(window, cx);
            }
            self.prompt_mode.update(cx, |prompt_mode, cx| match kind {
                JobKind::Question(id) => prompt_mode.reveal_question(id, cx),
                _ => prompt_mode.reveal_task(cx),
            });
        }
    }
}

