edit('src/prompt_mode.rs', [
("""    /// A reply is a row per piece of text and per tool call, in the order they
    /// happened; text with nothing in it yet is left out.""", """    /// Two folders, each an empty project, named for a test.
    fn two_projects(name: &str) -> (PathBuf, PathBuf) {
        let base = std::env::temp_dir().join(format!("suspense-{name}-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&base);
        let dirs = [base.join("alpha"), base.join("beta")];
        for dir in &dirs {
            std::fs::create_dir_all(dir).unwrap();
            std::fs::write(dir.join("piton.config.pi"), "").unwrap();
        }
        let [a, b] = dirs.map(|dir| std::fs::canonicalize(dir).unwrap());
        (a, b)
    }

    /// Switching projects leaves the work of the one left running in the
    /// background: its run still writes into it, never into the project on
    /// screen, and switching back shows it just as it is, loading nothing
    /// again.
    #[gpui_kit::test]
    async fn a_project_left_keeps_its_work_running(cx: &mut TestAppContext) {
        let (a, b) = two_projects("background-work");
        let (prompt_mode, handle) = open(cx);
        cx.update(|cx| ProjectDirectory::set(a.clone(), cx));
        cx.run_until_parked();
        let (task, question) = cx
            .update_window(handle, |_, _, cx| {
                prompt_mode.update(cx, |this, cx| {
                    let ix = this.push_task("Work in alpha".into(), cx);
                    this.working = true;
                    this.apply_event(ix, HarnessEvent::TextStarted, cx);
                    let question = this.start_test_question("Ask in alpha", cx);
                    (ix, question)
                })
            })
            .unwrap();

        cx.update(|cx| ProjectDirectory::set(b.clone(), cx));
        cx.run_until_parked();
        prompt_mode.update(cx, |this, cx| {
            assert!(this.tasks.is_empty() && this.asks.is_empty() && !this.working);
            assert!(this.is_working(), "alpha's work stopped counting");
            let busy = this.busy_projects();
            assert_eq!(busy.len(), 1);
            assert_eq!(busy[0].project_dir, a);
            assert_eq!(busy[0].task.as_deref(), Some("Work in alpha"));
            assert_eq!(busy[0].questions, [(question, "Ask in alpha".into())]);
            let jobs = this.running_jobs();
            assert_eq!(
                jobs.iter().map(|job| job.title.to_string()).collect::<Vec<_>>(),
                ["Task · alpha", "Question · alpha"]
            );
            assert!(jobs.iter().all(|job| job.project.as_ref() == Some(&a)));

            // Alpha's run writes back into alpha, not beta on screen.
            this.in_project(&a, cx, |this, cx| {
                this.apply_event(task, HarnessEvent::TextDelta("Still going.".into()), cx);
                this.update_ask(question, |ask| ask.end(), cx);
            });
            assert!(this.tasks.is_empty() && this.asks.is_empty());
            assert_eq!(this.project_dir.as_ref(), Some(&b));
        });

        cx.update(|cx| ProjectDirectory::set(a.clone(), cx));
        cx.run_until_parked();
        prompt_mode.update(cx, |this, _| {
            assert_eq!(this.tasks.len(), 1, "alpha's tasks were loaded again");
            assert!(this.working);
            assert!(this.tasks[0].reply.text().contains("Still going."));
            assert_eq!(this.asks.len(), 1);
            assert!(!this.asks[0].task.status.is_active());
            // Now on screen, alpha's jobs are no longer headed with its name.
            assert_eq!(
                this.running_jobs()
                    .iter()
                    .map(|job| job.title.to_string())
                    .collect::<Vec<_>>(),
                ["Task"]
            );
        });
        std::fs::remove_dir_all(a.parent().unwrap()).ok();
    }

    /// A reply is a row per piece of text and per tool call, in the order they
    /// happened; text with nothing in it yet is left out."""),
])

edit('src/main_window.rs', [
("""    /// While a prompt runs, quitting or closing the window asks first: Keep""", """    /// Switching projects stops a rescope search and closes its panel; the
    /// project indicator marks the busy project left, and quitting still asks
    /// while only it is working. Its task is listed with its name, and
    /// revealing it switches back to it; a build in it leaves Build free in
    /// the project on screen.
    #[gpui_kit::test]
    async fn switching_projects_keeps_the_one_left_running(cx: &mut TestAppContext) {
        let base = std::env::temp_dir().join(format!("suspense-switching-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&base);
        for name in ["alpha", "beta"] {
            std::fs::create_dir_all(base.join(name).join("spec")).unwrap();
            std::fs::write(base.join(name).join("piton.config.pi"), "").unwrap();
        }
        let (a, b) = (
            std::fs::canonicalize(base.join("alpha")).unwrap(),
            std::fs::canonicalize(base.join("beta")).unwrap(),
        );
        cx.update(|cx| {
            gpui_kit::init(cx);
            piton_syntax::init();
            ProjectDirectory::init(cx);
            super::bind_keys(cx);
            ProjectDirectory::set(a.clone(), cx);
        });
        let mut main = None;
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|cx| MainWindow::new(window, cx));
            main = Some(view.clone());
            Root::new(view, window, cx)
        });
        let main = main.unwrap();
        let handle = window.into();
        cx.run_until_parked();
        let (prompt_mode, ribbon) =
            main.read_with(cx, |main, _| (main.prompt_mode.clone(), main.ribbon.clone()));
        prompt_mode.update(cx, |prompt_mode, cx| {
            prompt_mode.start_test_question("Still thinking in alpha", cx);
        });
        cx.update_window(handle, |_, window, cx| {
            main.update(cx, |main, cx| main.open_rescope(window, cx));
        })
        .unwrap();
        assert!(main.read_with(cx, |main, _| main.rescope.is_some()));

        cx.update(|cx| ProjectDirectory::set(b.clone(), cx));
        cx.run_until_parked();
        assert!(
            main.read_with(cx, |main, _| main.rescope.is_none() && !main.panel_open()),
            "the rescope search outlived the switch"
        );
        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            assert!(window.try_find("project-busy-elsewhere").is_some());
        })
        .unwrap();
        let jobs = ribbon.read_with(cx, |ribbon, _| ribbon.jobs().to_vec());
        assert_eq!(jobs.len(), 1, "{jobs:?}");
        assert_eq!(jobs[0].title.as_ref(), "Question · alpha");
        assert_eq!(jobs[0].project.as_ref(), Some(&a));

        // A build in alpha doesn't hold up Build in beta.
        ribbon.update(cx, |ribbon, cx| ribbon.set_building_in(a.clone(), cx));
        assert!(ribbon.read_with(cx, |ribbon, cx| ribbon.can_build(cx)));

        // Quitting asks, though nothing runs in beta.
        cx.update_window(handle, |_, window, cx| {
            window.dispatch_action(Box::new(crate::app::Quit), cx)
        })
        .unwrap();
        cx.wait_for(handle, TIMEOUT, |window, _| {
            window.try_find("cancel").is_some()
        })
        .await;
        cx.update_window(handle, |_, window, cx| window.click("cancel", cx))
            .unwrap();
        cx.run_until_parked();

        // Revealing alpha's question switches back to alpha.
        cx.update_window(handle, |_, window, cx| {
            main.update(cx, |main, cx| {
                main.reveal_job(jobs[0].kind, jobs[0].project.clone(), window, cx)
            });
        })
        .unwrap();
        cx.run_until_parked();
        assert_eq!(cx.update(|cx| ProjectDirectory::get(cx)), Some(a.clone()));
        prompt_mode.read_with(cx, |prompt_mode, _| {
            assert_eq!(prompt_mode.running_jobs().len(), 1);
            assert!(prompt_mode.running_jobs()[0].project.is_none());
        });
        std::fs::remove_dir_all(&base).ok();
    }

    /// While a prompt runs, quitting or closing the window asks first: Keep"""),
])
